import * as React from 'react';
import List from '@tecton-mui/ui/List';
import ListItem from '@tecton-mui/ui/ListItem';
import ListItemButton from '@tecton-mui/ui/ListItemButton';
import ListItemIcon from '@tecton-mui/ui/ListItemIcon';
import ListItemText from '@tecton-mui/ui/ListItemText';
import IconButton from '@tecton-mui/ui/IconButton';
import Icon, { type IconProps } from '@tecton-mui/ui/Icon';

function CheckBoxIcon(props: Omit<IconProps, 'name'>) {
  return <Icon name="checkbox-checked" variant="filled" {...props} />;
}

function CheckBoxOutlineBlankIcon(props: Omit<IconProps, 'name'>) {
  return <Icon name="checkbox-unchecked" {...props} />;
}

export default function CheckboxList() {
  const [checked, setChecked] = React.useState([0]);

  const handleToggle = (value: number) => () => {
    const currentIndex = checked.indexOf(value);
    const newChecked = [...checked];

    if (currentIndex === -1) {
      newChecked.push(value);
    } else {
      newChecked.splice(currentIndex, 1);
    }

    setChecked(newChecked);
  };

  return (
    <List sx={{ width: '100%', maxWidth: 360, bgcolor: 'background.paper' }}>
      {[0, 1, 2, 3].map((value) => {
        const labelId = `checkbox-list-label-${value}`;
        const labelValue = `Line item ${value + 1}`;
        const isChecked = checked.includes(value);
        const SelectionIcon = isChecked ? CheckBoxIcon : CheckBoxOutlineBlankIcon;

        return (
          <ListItem
            key={value}
            secondaryAction={
              <IconButton edge="end" aria-label={`see comments for ${labelValue}`}>
                <Icon name="chat" />
              </IconButton>
            }
            disablePadding
          >
            <ListItemButton
              role="checkbox"
              aria-checked={isChecked}
              aria-labelledby={labelId}
              onClick={handleToggle(value)}
              dense
            >
              <ListItemIcon>
                <SelectionIcon
                  size="medium"
                  sx={{
                    color: isChecked ? 'primary.main' : 'text.secondary',
                    padding: '2px',
                    boxSizing: 'content-box',
                  }}
                />
              </ListItemIcon>
              <ListItemText id={labelId} primary={labelValue} />
            </ListItemButton>
          </ListItem>
        );
      })}
    </List>
  );
}
